    ctx2.fillRect(x - 2, y - 2, w + 4, h + 4);
    ctx2.fillStyle = "#d8a040";
    ctx2.fillRect(x - 2, y - 2, w + 4, h + 3);
    ctx2.fillStyle = "#ffe08a";
    ctx2.fillRect(x - 1, y - 2, w + 2, 1);
